const httpItem = $input.first();
const rawHtml = (httpItem && httpItem.json && httpItem.json.data) ? String(httpItem.json.data) : '';
const html = rawHtml.toLowerCase();

const inputJson = $('Set Website URL').first().json;
const body = inputJson || {};
const websiteUrl = body.website_url || '';
const userEmail = body.user_email || '';

const has = (patterns) => patterns.some(p => html.includes(p));

const hasGTM = has(['googletagmanager.com', 'gtm-', 'gtag(', 'gtag.js']);
const hasMetaPixel = has(['connect.facebook.net', 'fbevents.js', 'fbq(']);
const hasHotjar = has(['static.hotjar.com', 'hotjar.com', 'hj(', '_hjsettings']);
const hasCookieConsent = has(['cookie-consent', 'cookieconsent', 'cookie consent', 'cookie banner', 'cookiebot', 'onetrust', 'we use cookies', 'accept cookies', 'gdpr']);

const trackers = [];
if (hasGTM) trackers.push('Google Tag Manager');
if (hasMetaPixel) trackers.push('Meta Pixel');
if (hasHotjar) trackers.push('Hotjar');

// Derive origin (scheme + host) from the website URL
let origin = websiteUrl.trim().replace(/\/+$/, '');
const schemeMatch = origin.match(/^(https?:\/\/[^/]+)/i);
origin = schemeMatch ? schemeMatch[1] : ('https://' + origin.replace(/^https?:\/\//i, '').split('/')[0]);

const resolveUrl = (input) => {
  const raw = String(input || '').trim();
  if (!raw) return '';
  if (/^https?:\/\//i.test(raw)) return raw;
  if (raw.indexOf('//') === 0) return 'https:' + raw;
  if (raw.charAt(0) === '/') return origin + raw;
  return origin + '/' + raw;
};

// Host of the audited site, used to reject third-party privacy links
// (e.g. policies.google.com, facebook.com/privacy) so only the site's own
// policy is assessed.
const originHost = origin.replace(/^https?:\/\//i, '').toLowerCase();
const isSameHost = (u) => {
  const raw = String(u || '').toLowerCase();
  if (!raw) return false;
  const mm = raw.match(/^https?:\/\/([^/]+)/i);
  if (!mm) return true; // relative URL -> resolved against origin, same host
  const host = mm[1];
  return host === originHost || host.endsWith('.' + originHost) || originHost.endsWith('.' + host);
};

// Find the privacy-policy link in the raw HTML. Prefer a page linked as
// "Privacy Policy" (or data protection); never select a page linked only
// as "POPIA", so a POPIA-titled page is not the one assessed.
let privacyAnchorUrl = '';
let dataProtectionAnchorUrl = '';
const anchorRegex = /<a[^>]*href=["\']([^"\']+)["\'][^>]*>([\s\S]*?)<\/a>/gi;
let m;
while ((m = anchorRegex.exec(rawHtml)) !== null) {
  const href = m[1] || '';
  const inner = (m[2] || '').toLowerCase();
  const hrefLower = href.toLowerCase();
  const isPrivacy = /privacy/.test(hrefLower) || /privacy/.test(inner);
  const isDataProtection = /data-protection|data_protection/.test(hrefLower) || /data protection|protection of personal information/.test(inner);
  if (isPrivacy) {
    const resolved = resolveUrl(href);
    // Skip third-party privacy links; only accept one on the audited site.
    if (isSameHost(resolved)) {
      if (!privacyAnchorUrl) privacyAnchorUrl = resolved;
      break;
    }
    continue;
  }
  if (isDataProtection && !dataProtectionAnchorUrl) {
    const resolvedDp = resolveUrl(href);
    if (isSameHost(resolvedDp)) dataProtectionAnchorUrl = resolvedDp;
  }
}
const anchorPolicyUrl = privacyAnchorUrl || dataProtectionAnchorUrl;

const textMentionsPolicy = has(['privacy-policy', 'privacy policy', 'privacypolicy', '/privacy', 'popia', 'data protection', 'protection of personal information']);

// Build the list of URLs to fetch. If a real anchor link was found, trust it.
// Otherwise fall back to common privacy-policy paths. This covers SPAs / Shopify
// stores where the footer policy link is rendered by JavaScript and never appears
// in the raw HTML we can read.
let candidates;
if (anchorPolicyUrl) {
  candidates = [anchorPolicyUrl];
} else {
  const commonPaths = ['/privacy-policy', '/privacy', '/privacy-notice', '/legal/privacy', '/pages/privacy-policy', '/policies/privacy-policy'];
  candidates = commonPaths.map(p => origin + p);
}

const totalCandidates = candidates.length;
return candidates.map((url, idx) => ({
  json: {
    website_url: websiteUrl,
    user_email: userEmail,
    trackers: trackers,
    has_cookie_consent: hasCookieConsent,
    text_mentions_policy: textMentionsPolicy,
    has_anchor: anchorPolicyUrl !== '',
    candidate_index: idx,
    total_candidates: totalCandidates,
    fetch_url: url,
  },
}));

const base = $('Analyze Website Content').first().json;
const websiteUrl = base.website_url || '';
const userEmail = base.user_email || '';
const trackers = base.trackers || [];
const hasTrackers = trackers.length > 0;
const hasCookieConsent = !!base.has_cookie_consent;
const textMentionsPolicy = !!base.text_mentions_policy;
const hasAnchor = !!base.has_anchor;

// Inspect every fetched candidate page and pick the first that genuinely looks
// like a privacy policy (real content, not a soft-404 or empty shell).
const fetched = $input.all();
const analyzeItems = $('Analyze Website Content').all();

const extractText = (rawHtml) => String(rawHtml || '')
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

const looksLikePolicy = (text) => {
  const t = text.toLowerCase();
  if (text.length < 500) return false; // too short - likely a 404 / empty shell
  const isNotFound = /(^|\W)404(\W|$)|page not found|page you (were|are) looking for|does\s?n.?t exist|could\s?n.?t be found/.test(t);
  if (isNotFound) return false;
  const mentionsPrivacy = /(privacy|popia|personal information|data protection)/.test(t);
  return mentionsPrivacy;
};

let policyText = '';
let policyUrl = '';
for (let i = 0; i < fetched.length; i++) {
  const it = fetched[i];
  const data = (it && it.json && it.json.data) ? it.json.data : '';
  const text = extractText(data);
  if (looksLikePolicy(text)) {
    policyText = text;
    policyUrl = (analyzeItems[i] && analyzeItems[i].json) ? analyzeItems[i].json.fetch_url : '';
    break;
  }
}

const policyFound = policyText !== '';
const canGrade = policyFound;
const hasPrivacyPolicy = policyFound || hasAnchor || textMentionsPolicy;

// ---- Site-level compliance score (presence checks) ----
let siteScore = 100;
const gaps = [];

if (!hasPrivacyPolicy) {
  siteScore -= 35;
  gaps.push('No Privacy Policy or POPIA notice link was found on the page.');
}
if (!hasCookieConsent) {
  siteScore -= 30;
  gaps.push('No cookie consent banner was detected.');
}
if (hasTrackers && !hasCookieConsent) {
  siteScore -= 25;
  gaps.push('Tracking scripts (' + trackers.join(', ') + ') load without a cookie consent mechanism, which may collect personal data without consent.');
}
if (hasTrackers && !hasPrivacyPolicy) {
  siteScore -= 10;
  gaps.push('Tracking scripts are present but no Privacy Policy discloses how visitor data is processed.');
}
if (siteScore < 0) siteScore = 0;

const gapCount = gaps.length;
const summaryLine = gapCount === 0
  ? 'No compliance gaps were identified.'
  : (gapCount + (gapCount === 1 ? ' Gap was identified.' : ' Gaps were identified.'));

const gapsForList = gapCount === 0
  ? ['No major site-level compliance gaps detected in this automated scan.']
  : gaps.slice();

let siteColor = '#e53e3e';
if (siteScore >= 70) siteColor = '#38a169';
else if (siteScore >= 40) siteColor = '#dd6b20';

let siteScoreMessage;
if (siteScore >= 70) siteScoreMessage = "You've built a strong POPIA foundation. A few small refinements will help you stay ahead and keep visitor trust high.";
else if (siteScore >= 40) siteScoreMessage = "You're well on your way, and a handful of focused improvements will strengthen your site's POPIA compliance.";
else siteScoreMessage = 'There are a number of improvements needed, some key additions will make a big difference to your site compliance.';

// ---- Privacy Policy Quality grading (keyword heuristic, approximate) ----
let qualityScore = null;
let qualityBand = 'Not assessed';
let qualityMessage = '';
let criteriaResult = [];

if (canGrade) {
  const t = policyText.toLowerCase();
  const test = (re) => re.test(t);

  // 1. Information Officer & Entity Contact Details (weight 10)
  const hasIO = test(/information officer/);
  const hasEmail = test(/[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}/);
  const hasGenericEmail = test(/(info|support|admin|contact|hello|enquiries)@/);
  const hasAddress = test(/postal address|physical address|p\.?o\.? box|street|avenue|\broad\b|building|floor|\d{4},?\s*(south africa)?/);
  let c1 = 0;
  if (hasIO && hasEmail && hasAddress) c1 = 2;
  else if (hasIO || hasEmail || hasGenericEmail) c1 = 1;

  // 2. Specified Purposes of Processing (weight 15)
  const hasPurpose = test(/purpose(s)? (of|for) (processing|collection)|why we (collect|process)|purpose of processing|for the (specific )?purpose/);
  const hasVaguePurpose = test(/improve (our )?services|general business purposes|business purposes/);
  const hasSpecificPurpose = test(/newsletter|order|delivery|billing|invoic|account|marketing|support|fulfil/);
  let c2 = 0;
  if (hasPurpose && hasSpecificPurpose) c2 = 2;
  else if (hasPurpose || hasVaguePurpose) c2 = 1;

  // 3. Consent & Direct Marketing Rules (weight 15)
  const hasOptIn = test(/opt[- ]?in/);
  const hasOptOut = test(/opt[- ]?out|unsubscribe|withdraw consent|withdraw your consent/);
  const hasMarketing = test(/direct marketing|marketing communications|electronic communications/);
  let c3 = 0;
  if (hasOptIn && (hasMarketing || hasOptOut)) c3 = 2;
  else if (hasOptOut) c3 = 1;

  // 4. Data Subject Rights & PAIA Alignment (weight 20)
  let rightsCount = 0;
  if (test(/right to access|request access/)) rightsCount++;
  if (test(/correct(ion)?|rectif/)) rightsCount++;
  if (test(/delet(e|ion)|erasure/)) rightsCount++;
  if (test(/object(ion)? to (the )?processing|right to object/)) rightsCount++;
  const hasRegulator = test(/information regulator/);
  const hasPAIA = test(/paia|promotion of access to information/);
  let c4 = 0;
  if (rightsCount >= 3 && hasRegulator && hasPAIA) c4 = 2;
  else if (rightsCount >= 1) c4 = 1;

  // 5. Cross-Border Data Transfers (weight 15)
  const hasCrossBorder = test(/cross[- ]?border|transborder|outside (south africa|the republic)|international(ly)? transfer|transfer.*(abroad|another country)/);
  const hasCloud = test(/cloud|aws|amazon web services|azure|google cloud|servers? (located|hosted)/);
  const hasSafeguard = test(/adequate (protection|safeguards)|similar (law|protection)|binding corporate rules|standard contractual|appropriate safeguards/);
  let c5 = 0;
  if (hasCrossBorder && hasSafeguard) c5 = 2;
  else if (hasCrossBorder || hasCloud) c5 = 1;

  // 6. Security & Data Retention Policies (weight 15)
  const hasSecurity = test(/security (measures|safeguards)|encryption|access control|technical and organ(i|iz|is)ational/);
  const hasRetentionCriteria = test(/retention (period|schedule)|retain.*(for a period|until|criteria|purpose)|how long we (keep|retain)|securely destroy/);
  const hasVagueRetention = test(/as long as (necessary|needed)|retain (data )?indefinitely/);
  let c6 = 0;
  if (hasSecurity && hasRetentionCriteria) c6 = 2;
  else if (hasSecurity || hasRetentionCriteria || hasVagueRetention) c6 = 1;

  // 7. Plain Language & Accessibility (weight 10) - length proxy
  let c7 = 0;
  if (policyText.length > 1500) c7 = 2;
  else if (policyText.length > 300) c7 = 1;

  const criteria = [
    { label: 'Information Officer & Entity Contact Details', weight: 10, points: c1 },
    { label: 'Specified Purposes of Processing', weight: 15, points: c2 },
    { label: 'Consent & Direct Marketing Rules', weight: 15, points: c3 },
    { label: 'Data Subject Rights & PAIA Alignment', weight: 20, points: c4 },
    { label: 'Cross-Border Data Transfers', weight: 15, points: c5 },
    { label: 'Security & Data Retention Policies', weight: 15, points: c6 },
    { label: 'Plain Language & Accessibility', weight: 10, points: c7 },
  ];

  let weighted = 0;
  for (const c of criteria) { weighted += c.weight * c.points; }
  qualityScore = Math.round(weighted / 2);

  if (qualityScore >= 85) {
    qualityBand = 'Highly Effective & POPIA Compliant';
    qualityMessage = 'Your privacy policy is thorough and well-aligned with POPIA. A light periodic review will keep it current as your business grows.';
  } else if (qualityScore >= 65) {
    qualityBand = 'Above Average';
    qualityMessage = 'Your privacy policy covers the essentials well. Strengthening a few areas will take it from good to fully POPIA-aligned.';
  } else {
    qualityBand = 'Needs Work';
    qualityMessage = 'Your privacy policy needs a few key updates.';
  }

  criteriaResult = criteria.map(function (c) {
    const status = c.points === 2 ? 'Compliant' : (c.points === 1 ? 'Partial' : 'Non-Compliant');
    return { criterion: c.label, weight: c.weight, points: c.points, max_points: 2, status: status };
  });
}

return [{
  json: {
    website_url: websiteUrl,
    score: siteScore,
    score_color: siteColor,
    trackers_detected: trackers,
    has_cookie_consent: hasCookieConsent,
    has_privacy_policy: hasPrivacyPolicy,
    can_grade: canGrade,
    policy_url: policyUrl,
    gap_count: gapCount,
    summary_line: summaryLine,
    site_score_message: siteScoreMessage,
    gaps: gapsForList,
    quality_score: qualityScore,
    quality_band: qualityBand,
    quality_message: qualityMessage,
    quality_criteria: criteriaResult,
  },
}];
